// Bit-exact parity test for the GDN causal-conv1d DECODE chain.
// Compares C++ output against vectors generated by the REAL Python helpers
// (tools/gen_conv_vectors.py), byte-for-byte, not by tolerance.
#include "../src/gdn_conv.h"

#include <mlx/mlx.h>

#include <cstdint>
#include <cstdio>
#include <string>

namespace mx = mlx::core;
using namespace veystrix::engine;

static bool bit_equal(const mx::array& a, const mx::array& b) {
  if (a.shape() != b.shape()) return false;
  mx::array av = mx::astype(mx::reshape(a, {-1}), mx::uint32);
  mx::array bv = mx::astype(mx::reshape(b, {-1}), mx::uint32);
  mx::eval(av, bv);
  if (av.size() != bv.size()) return false;
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (size_t i = 0; i < av.size(); ++i)
    if (pa[i] != pb[i]) return false;
  return true;
}

static void dump_first_diff(const char* label, const mx::array& a,
                            const mx::array& b) {
  mx::array av = mx::astype(mx::reshape(a, {-1}), mx::uint32);
  mx::array bv = mx::astype(mx::reshape(b, {-1}), mx::uint32);
  mx::eval(av, bv);
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (size_t i = 0; i < av.size(); ++i) {
    if (pa[i] != pb[i]) {
      std::fprintf(stderr, "  %s first diff at %zu: got 0x%08x expected 0x%08x\n",
                   label, i, pa[i], pb[i]);
      return;
    }
  }
}

int main(int argc, char** argv) {
  if (argc < 2) {
    std::fprintf(stderr, "usage: %s <vectordir>\n", argv[0]);
    return 2;
  }
  std::string dir = argv[1];
  auto load = [&](const char* n) { return mx::load(dir + "/" + n + ".npy"); };

  mx::array conv_input = load("conv_input");
  mx::array conv_weight = load("conv_weight");
  mx::array expected = load("expected");
  mx::array expected_silu = load("expected_silu");

  mx::array conv_out = gdn_causal_conv_decode(conv_input, conv_weight);
  mx::eval(conv_out);
  if (!bit_equal(conv_out, expected)) {
    std::fprintf(stderr, "FAIL: pre-silu conv output differs\n");
    dump_first_diff("conv_out", conv_out, expected);
    return 1;
  }

  mx::array silu_out = gdn_causal_conv_decode_silu(conv_input, conv_weight);
  mx::eval(silu_out);
  if (!bit_equal(silu_out, expected_silu)) {
    std::fprintf(stderr, "FAIL: silu output differs\n");
    dump_first_diff("silu_out", silu_out, expected_silu);
    return 1;
  }

  std::printf("test_conv OK\n");
  return 0;
}
